const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI peer-to-peer ledger auditor for Mana Khata Book. You audit neighborhood micro-credit ledgers (carpool petrol splits, daily vegetable sharing, group buying prepayments). Track dues aging (0-15d, 16-30d, 31-60d, 60d+), calculate resident community repayment trust scores, and draft courteous reminder messages.

Analyze the input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{
  "residentId": "RES-8841",
  "totalOutstandingReceivable": 4650,
  "totalOutstandingPayable": 850,
  "netBalance": 3800,
  "communityRepaymentTrustScore": 92,
  "agingBreakdown": {
    "zeroToFifteenDays": 3200,
    "sixteenToThirtyDays": 950,
    "thirtyOneToSixtyDays": 500,
    "overSixtyDays": 0
  },
  "friendlyReminderDigest": "Hi Neighbor! Friendly reminder from Mana Split Khata: ₹950 from the festival pooja flowers & carpool pool is pending for settlement when you get a chance."
}

Rules:
- Return pure JSON only, no markdown wrapping.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"residentId":"RES-8841","totalOutstandingReceivable":4650,"totalOutstandingPayable":850,"netBalance":3800,"communityRepaymentTrustScore":92,"agingBreakdown":{"zeroToFifteenDays":3200,"sixteenToThirtyDays":950,"thirtyOneToSixtyDays":500,"overSixtyDays":0},"friendlyReminderDigest":"Hi Neighbor! Friendly reminder from Mana Split Khata: ₹950 from the festival pooja flowers & carpool pool is pending for settlement when you get a chance."} } }];
}
